  Let $F$ and $F_n$, $n \in \mathbb{N}$, be cumulative distribution functions of
  probability measures $\mu$ and $\mu_n$, $n \in \mathbb{N}$, respectively, i.e.,
  \begin{align*}
      F(x) = \; & \mu\big[(-\infty,x]\big] & & \text{for $x \in \mathbb{R}$} \\
      F_n(x) = \; & \mu_n \big[(-\infty,x]\big] & & \text{for $x \in \mathbb{R}$ and $n \in \mathbb{N}$.}
  \end{align*}
  If $\lim_{n \to \infty} F_n(x) = F(x)$ for all continuity points $x$ of $F$,
  then $\lim_{n \to \infty} \mu_n = \mu$ in the sense of weak convergence
  of measures, Definition~\ref{def:convergence-in-distribution}.
\end{theorem}

