\begin{definition}[Extended cumulative distribution function]
  \label{def:cdf-extend}
  \uses{def:cdf}
  \lean{CumulativeDistributionFunction.extend}
  \leanok
  The extension $\widetilde{F}$ of a c.d.f. $F$ is the function
  \begin{align*}
    \widetilde{F} \colon [-\infty,+\infty] \to [0,1]
  \end{align*}
  given by
  \begin{align*}
    \widetilde{F}(x) = \begin{cases}
      0 & \; \text{ if } x = -\infty \\
      F(x) & \; \text{ if } -\infty < x < +\infty \\
      1 & \; \text{ if } x = +\infty .
      \end{cases}
  \end{align*}
\end{definition}

