\begin{definition}[One over one minus cumulative distribution function]
  \label{def:one-div-one-sub-cdf}
  \uses{def:cdf-extend}
  \lean{CumulativeDistributionFunction.oneDivOneSub}
  \leanok
  The transform $\frac{\mathbf{1}}{\mathbf{1}-\widetilde{F}}$ of a c.d.f. $F$ is the function
  \begin{align*}
    \frac{\mathbf{1}}{\mathbf{1}-\widetilde{F}} \colon [-\infty,+\infty] \to [1,+\infty]
  \end{align*}
  given by
  \begin{align*}
    \frac{\mathbf{1}}{\mathbf{1}-\widetilde{F}}(x) = \begin{cases}
      1 & \; \text{ if } \widetilde{F}(x) = 0 \\
      \frac{1}{1-\widetilde{F}(x)} & \; \text{ if } 0 < \widetilde{F}(x) < 1 \\
      +\infty & \; \text{ if } \widetilde{F}(x) = 1 ,
      \end{cases}
  \end{align*}
  where $\widetilde{F} \colon [-\infty,+\infty] \to [0,1]$ is the extension of the c.d.f. $F$.
\end{definition}

