n32238.content:
\begin{theorem}[Three types of extreme value distributions [Fisher-Tippett-Gnedenko]]
  \label{thm:three-types-of-extr-val-distr}
  \uses{def:extr-val-distr,
    def:std-Gumbel-cdf, def:std-Frechet-cdf, def:std-Weibull-cdf}
  \lean{CumulativeDistributionFunction.IsExtremeValueDistr.classification}
  \leanok
  For any extreme value distribution $G$, one of the following holds:
  \begin{description}
    \item{($\Lambda$)}
      $G = A . \Lambda$ for some $A \in \mathrm{Aff}^+_{\mathbb{R}}$;
    \item{($\Phi_{{}}$)}
      $G = A . \Phi_{\alpha}$ for some $A \in \mathrm{Aff}^+_{\mathbb{R}}$ and $\alpha > 0$;
    \item{($\Psi_{{}}$)}
      $G = A . \Psi_{\alpha}$ for some $A \in \mathrm{Aff}^+_{\mathbb{R}}$ and $\alpha > 0$.
  \end{description}
  In particular, the only three possible types of extreme value distributions
  are the type of the Gumbel c.d.f., the type of
  the Fr\'echet c.d.f. $\Phi_{\alpha}$ for $\alpha > 0$, and
  the type of the Weibull c.d.f. $\Psi_{\alpha}$ for $\alpha > 0$.
\end{theorem}

n32240.content:
\begin{definition}
  \label{def:lc-inverse}
  \lean{lcInv}
  \leanok
  Let $f \colon R \to S$ be a function (usually assumed nondecreasing).
  The left-continuous inverse of $f$ is the function ${f}^{\rightarrow 1} \colon S \to R$
  given by
  \begin{align*}
    {f}^{\rightarrow 1}(y) := \inf \big\{ x \in R \; \big| \; f(x) \ge y \big\}
    \qquad \text{ for } y \in S.
  \end{align*}
  The right-continuous inverse ${f}^{\leftarrow 1} \colon S \to R$ is analoguously defined by
  \begin{align*}
    {f}^{\leftarrow 1}(y) := \sup \big\{ x \in R \; \big| \; f(x) \le y \big\}
    \qquad \text{ for } y \in S.
  \end{align*}
\end{definition}

