\begin{lemma}[Finding an interval with high overlap]
  \label{lem:exists-high-overlap-interval}
  %\uses{}
  \lean{exists_interval_measure_inter_gt_mul_measure}
  \leanok
  Let $A \subset \mathbb{R}$ be a measurable set such that $0 < \Lambda[A] < +\infty$.
  Then for any $r \in [0,1)$, there exists a nontrivial interval $J \subset \mathbb{R}$
  (a subset of the real line which is connected and has nonempty interior)
  such that
  \begin{align*}
    \Lambda[A \cap J] \; > \; r \, \Lambda[J] .
  \end{align*}
\end{lemma}

